const inp = $json;
let text;
if (inp.success === true && inp.report) {
  const r = inp.report;
  const L = [];
  L.push('📊 REPORT ANALISI AI');
  L.push('🤖 Provider: ' + (inp.provider || 'n/d'));
  L.push('💭 Sentiment: ' + (r.sentiment || 'n/d'));
  L.push('');
  L.push('📂 CATEGORIE:');
  const cat = r.categorie;
  if (Array.isArray(cat)) {
    if (cat.length === 0) L.push('  • nessuna');
    cat.forEach(c => L.push('  • ' + (typeof c === 'string' ? c : JSON.stringify(c))));
  } else if (cat && typeof cat === 'object') {
    const keys = Object.keys(cat);
    if (keys.length === 0) L.push('  • nessuna');
    keys.forEach(k => {
      const v = cat[k];
      if (Array.isArray(v) && v.length > 0) {
        L.push('  [' + k + ']');
        v.forEach(i => L.push('    • ' + i));
      } else if (typeof v === 'string') {
        L.push('  [' + k + '] ' + v);
      }
    });
  } else { L.push('  • n/d'); }
  L.push('');
  L.push('✅ AZIONI OPERATIVE:');
  const az = Array.isArray(r.azioni_operative) ? r.azioni_operative : [];
  if (az.length === 0) L.push('  • nessuna');
  az.forEach(a => L.push('  • ' + (typeof a === 'string' ? a : JSON.stringify(a))));
  L.push('');
  L.push('🚨 URGENZE:');
  const ur = Array.isArray(r.urgenze) ? r.urgenze : [];
  if (ur.length === 0) L.push('  • nessuna');
  ur.forEach(u => L.push('  • ' + (typeof u === 'string' ? u : JSON.stringify(u))));
  text = L.join('\n');
} else {
  text = '⚠️ Analisi completata ma report non parseabile.\nErrore: ' + (inp.error || 'n/d') + '\nRaw: ' + String(inp.raw || '').slice(0, 300);
}
if (text.length > 4000) text = text.slice(0, 4000) + '\n…(troncato)';
const ts = new Date().toISOString().replace(/[:.]/g, '-');
return [{ json: { telegramText: text, reportJson: JSON.stringify(inp.report || inp, null, 2), reportName: 'report_' + ts + '.json' } }];
